/****************************************************************************
 * app/velaguard_app/velaguard_main.c
 *
 * VelaGuard boot entry (issue #01). Boot order is fixed:
 *   device id -> data dir -> startup log/event -> LVGL -> home UI -> loop
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <unistd.h>
#include <sys/boardctl.h>

#include <lvgl/lvgl.h>

#include "src/vg_device_id.h"
#include "src/vg_log.h"
#include "src/vg_ui_home.h"

#define VG_INPUT_DEVPATH "/dev/input0"

#undef NEED_BOARDINIT
#if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
#  define NEED_BOARDINIT 1
#endif

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;
  int ret;

  (void)argc;
  (void)argv;

  printf("===========================================\n");
  printf("  VelaGuard - Industrial Edge AI Gateway\n");
  printf("===========================================\n");

  vg_device_id_init();
  printf("[VG] Device ID: %s\n", vg_get_device_id());
  printf("[VG] Build mode: %s\n", vg_build_mode_str());

  ret = vg_log_init();
  if (ret < 0)
    {
      fprintf(stderr, "[VG] WARNING: Data directory init failed: %d\n", ret);
    }

  ret = vg_log_startup_event();
  if (ret < 0)
    {
      fprintf(stderr, "[VG] WARNING: Startup event log failed: %d\n", ret);
    }

  if (lv_is_initialized())
    {
      fprintf(stderr, "[VG] ERROR: LVGL already initialized\n");
      return -1;
    }

#ifdef NEED_BOARDINIT
  boardctl(BOARDIOC_INIT, 0);
#endif

  lv_init();
  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = VG_INPUT_DEVPATH;
#endif

  lv_nuttx_init(&info, &result);
  if (result.disp == NULL)
    {
      fprintf(stderr, "[VG] ERROR: LVGL display init failed\n");
      lv_deinit();
      return 1;
    }

  printf("[VG] LVGL display initialized\n");
  vg_ui_home_create();
  printf("[VG] Home screen created\n");
  printf("[VG] Entering event loop\n");

  while (1)
    {
      uint32_t idle = lv_timer_handler();

      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}

/****************************************************************************
 * app/velaguard_app/src/vg_device_id.h
 ****************************************************************************/

#ifndef APP_VELAGUARD_APP_SRC_VG_DEVICE_ID_H
#define APP_VELAGUARD_APP_SRC_VG_DEVICE_ID_H

#include <nuttx/config.h>
#include <stdbool.h>

#define VG_DEVICE_ID_MAX_LEN 40

void vg_device_id_init(void);
const char *vg_get_device_id(void);
bool vg_is_production_build(void);
const char *vg_build_mode_str(void);

#endif /* APP_VELAGUARD_APP_SRC_VG_DEVICE_ID_H */

/****************************************************************************
 * app/velaguard_app/src/vg_device_id.c
 *
 * Test (VG_BUILD_MODE=0): CONFIG_VG_DEVID_OVERRIDE
 * Production (VG_BUILD_MODE=1): STM32H750 UID @ 0x1FF1E800 -> velaguard_<24hex>
 * No runtime Device ID edit API in this slice.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "vg_device_id.h"

#define STM32_UID_BASE 0x1ff1e800u
#define STM32_UID_LEN  12

static char g_device_id[VG_DEVICE_ID_MAX_LEN];

void vg_device_id_init(void)
{
#if CONFIG_VG_BUILD_MODE == 0
  snprintf(g_device_id, sizeof(g_device_id), "%s", CONFIG_VG_DEVID_OVERRIDE);
#else
  const volatile uint8_t *uid = (const volatile uint8_t *)STM32_UID_BASE;
  int i;

  snprintf(g_device_id, sizeof(g_device_id), "velaguard_");
  for (i = 0; i < STM32_UID_LEN; i++)
    {
      snprintf(g_device_id + 10 + i * 2, 3, "%02x", uid[i]);
    }

  g_device_id[VG_DEVICE_ID_MAX_LEN - 1] = '\0';
#endif
}

const char *vg_get_device_id(void)
{
  return g_device_id;
}

bool vg_is_production_build(void)
{
#if CONFIG_VG_BUILD_MODE == 1
  return true;
#else
  return false;
#endif
}

const char *vg_build_mode_str(void)
{
  return vg_is_production_build() ? "production" : "test";
}

/****************************************************************************
 * app/velaguard_app/src/vg_log.h
 ****************************************************************************/

#ifndef APP_VELAGUARD_APP_SRC_VG_LOG_H
#define APP_VELAGUARD_APP_SRC_VG_LOG_H

int vg_log_init(void);
int vg_log_startup_event(void);

#endif /* APP_VELAGUARD_APP_SRC_VG_LOG_H */

/****************************************************************************
 * app/velaguard_app/src/vg_log.c
 *
 * Creates /data/velaguard/{configs,logs}, writes latest.log + events.jsonl
 * startup records. Call after vg_device_id_init().
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

#include "vg_device_id.h"
#include "vg_log.h"

#define VG_DATA_DIR    "/data/velaguard"
#define VG_CONFIGS_DIR "/data/velaguard/configs"
#define VG_LOGS_DIR    "/data/velaguard/logs"
#define VG_EVENTS_FILE "/data/velaguard/logs/events.jsonl"
#define VG_LOG_FILE    "/data/velaguard/logs/latest.log"

static int vg_mkdir_p(const char *path)
{
  char tmp[128];
  char *p;
  size_t len;

  snprintf(tmp, sizeof(tmp), "%s", path);
  len = strlen(tmp);
  if (len == 0)
    {
      return -EINVAL;
    }

  if (tmp[len - 1] == '/')
    {
      tmp[len - 1] = '\0';
    }

  for (p = tmp + 1; *p; p++)
    {
      if (*p == '/')
        {
          *p = '\0';
          if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
            {
              return -errno;
            }

          *p = '/';
        }
    }

  if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
    {
      return -errno;
    }

  return 0;
}

static uint64_t vg_get_uptime_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000ULL + (uint64_t)ts.tv_nsec / 1000000ULL;
}

static void vg_generate_boot_id(char *buf, size_t buflen)
{
  snprintf(buf, buflen, "%s-boot-%llu",
           vg_get_device_id(),
           (unsigned long long)vg_get_uptime_ms());
}

static const char *vg_get_time_quality(void)
{
  time_t now = time(NULL);
  struct tm *tm = gmtime(&now);

  if (tm != NULL && tm->tm_year > (2020 - 1900))
    {
      return "rtc";
    }

  return "unknown";
}

int vg_log_init(void)
{
  int ret;

  ret = vg_mkdir_p(VG_DATA_DIR);
  if (ret < 0)
    {
      fprintf(stderr, "[VG] Failed to create %s: %s\n",
              VG_DATA_DIR, strerror(-ret));
      return ret;
    }

  ret = vg_mkdir_p(VG_CONFIGS_DIR);
  if (ret < 0)
    {
      fprintf(stderr, "[VG] Failed to create %s: %s\n",
              VG_CONFIGS_DIR, strerror(-ret));
      return ret;
    }

  ret = vg_mkdir_p(VG_LOGS_DIR);
  if (ret < 0)
    {
      fprintf(stderr, "[VG] Failed to create %s: %s\n",
              VG_LOGS_DIR, strerror(-ret));
      return ret;
    }

  return 0;
}

int vg_log_startup_event(void)
{
  const char *dev_id = vg_get_device_id();
  const char *build_mode = vg_build_mode_str();
  const char *version = CONFIG_VG_FIRMWARE_VERSION;
  const char *time_quality = vg_get_time_quality();
  uint64_t uptime_ms = vg_get_uptime_ms();
  char boot_id[VG_DEVICE_ID_MAX_LEN + 32];
  FILE *fp;
  int ret = 0;

  vg_generate_boot_id(boot_id, sizeof(boot_id));

  fp = fopen(VG_LOG_FILE, "a");
  if (fp == NULL)
    {
      ret = -errno;
      fprintf(stderr, "[VG] Failed to open %s: %s\n",
              VG_LOG_FILE, strerror(errno));
    }
  else
    {
      if (fprintf(fp,
                  "[INFO ] [startup] VelaGuard boot | "
                  "device_id=%s build_mode=%s version=%s "
                  "boot_id=%s uptime_ms=%llu time_quality=%s\n",
                  dev_id, build_mode, version, boot_id,
                  (unsigned long long)uptime_ms, time_quality) < 0)
        {
          ret = -EIO;
        }

      if (fclose(fp) != 0 && ret == 0)
        {
          ret = -errno;
        }
    }

  fp = fopen(VG_EVENTS_FILE, "a");
  if (fp == NULL)
    {
      if (ret == 0)
        {
          ret = -errno;
        }

      fprintf(stderr, "[VG] Failed to open %s: %s\n",
              VG_EVENTS_FILE, strerror(errno));
    }
  else
    {
      if (fprintf(fp,
                  "{\"type\":\"boot\","
                  "\"device_id\":\"%s\","
                  "\"build_mode\":\"%s\","
                  "\"firmware_version\":\"%s\","
                  "\"boot_id\":\"%s\","
                  "\"uptime_ms\":%llu,"
                  "\"time_quality\":\"%s\"}\n",
                  dev_id, build_mode, version, boot_id,
                  (unsigned long long)uptime_ms, time_quality) < 0 &&
          ret == 0)
        {
          ret = -EIO;
        }

      if (fclose(fp) != 0 && ret == 0)
        {
          ret = -errno;
        }
    }

  printf("[VG] Boot event%s:\n", ret == 0 ? " written" : " console copy");
  printf("  device_id:        %s\n", dev_id);
  printf("  build_mode:       %s\n", build_mode);
  printf("  firmware_version: %s\n", version);
  printf("  boot_id:          %s\n", boot_id);
  printf("  uptime_ms:        %llu\n", (unsigned long long)uptime_ms);
  printf("  time_quality:     %s\n", time_quality);

  return ret;
}

/****************************************************************************
 * app/velaguard_app/src/vg_ui_home.c
 *
 * LVGL home for 480x272: title, device id, firmware, placeholder status
 * cards (Acquire / Alarm / Network / Audio / Time). No Device ID editor.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <lvgl/lvgl.h>

#include "vg_device_id.h"
#include "vg_ui_home.h"

#define VG_COLOR_BG       lv_color_hex(0x1a1a2e)
#define VG_COLOR_TITLE_BG lv_color_hex(0x16213e)
#define VG_COLOR_TEXT     lv_color_hex(0xe0e0e0)
#define VG_COLOR_GREEN    lv_color_hex(0x00c853)
#define VG_COLOR_YELLOW   lv_color_hex(0xffd600)
#define VG_COLOR_RED      lv_color_hex(0xff1744)
#define VG_COLOR_GRAY     lv_color_hex(0x616161)
#define VG_COLOR_BLUE     lv_color_hex(0x2979ff)
#define VG_COLOR_CARD_BG  lv_color_hex(0x222244)

#define VG_SCREEN_W      480
#define VG_SCREEN_H      272
#define VG_TITLE_H       32
#define VG_INFO_H        36
#define VG_STATUS_AREA_Y (VG_TITLE_H + VG_INFO_H + 4)
#define VG_STATUS_AREA_H (VG_SCREEN_H - VG_STATUS_AREA_Y - 4)
#define VG_CARD_COUNT    5
#define VG_CARD_GAP      4
#define VG_CARD_W        ((VG_SCREEN_W - (VG_CARD_COUNT + 1) * VG_CARD_GAP) \
                          / VG_CARD_COUNT)

static lv_obj_t *vg_create_title_bar(lv_obj_t *parent)
{
  lv_obj_t *bar = lv_obj_create(parent);
  lv_obj_t *title;
  lv_obj_t *badge;
  char mode_buf[32];

  lv_obj_set_size(bar, VG_SCREEN_W, VG_TITLE_H);
  lv_obj_align(bar, LV_ALIGN_TOP_LEFT, 0, 0);
  lv_obj_set_style_bg_color(bar, VG_COLOR_TITLE_BG, 0);
  lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(bar, 0, 0);
  lv_obj_set_style_radius(bar, 0, 0);
  lv_obj_set_style_pad_hor(bar, 8, 0);
  lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  title = lv_label_create(bar);
  lv_label_set_text(title, "VelaGuard");
  lv_obj_set_style_text_color(title, VG_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(title, &lv_font_montserrat_16, 0);

  badge = lv_label_create(bar);
  snprintf(mode_buf, sizeof(mode_buf), "[%s]", vg_build_mode_str());
  lv_label_set_text(badge, mode_buf);
  lv_obj_set_style_text_color(badge,
                              vg_is_production_build() ? VG_COLOR_GREEN
                                                       : VG_COLOR_YELLOW,
                              0);
  lv_obj_set_style_text_font(badge, &lv_font_montserrat_12, 0);

  return bar;
}

static lv_obj_t *vg_create_info_row(lv_obj_t *parent)
{
  lv_obj_t *row = lv_obj_create(parent);
  lv_obj_t *id_label;
  lv_obj_t *ver_label;
  char id_buf[64];
  char ver_buf[64];

  lv_obj_set_size(row, VG_SCREEN_W, VG_INFO_H);
  lv_obj_align(row, LV_ALIGN_TOP_LEFT, 0, VG_TITLE_H);
  lv_obj_set_style_bg_color(row, VG_COLOR_BG, 0);
  lv_obj_set_style_bg_opa(row, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(row, 0, 0);
  lv_obj_set_style_radius(row, 0, 0);
  lv_obj_set_style_pad_hor(row, 8, 0);
  lv_obj_set_style_pad_ver(row, 2, 0);
  lv_obj_set_flex_flow(row, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START,
                        LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER);

  snprintf(id_buf, sizeof(id_buf), "ID: %s", vg_get_device_id());
  id_label = lv_label_create(row);
  lv_label_set_text(id_label, id_buf);
  lv_obj_set_style_text_color(id_label, VG_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(id_label, &lv_font_montserrat_12, 0);

  snprintf(ver_buf, sizeof(ver_buf), "FW: %s", CONFIG_VG_FIRMWARE_VERSION);
  ver_label = lv_label_create(row);
  lv_label_set_text(ver_label, ver_buf);
  lv_obj_set_style_text_color(ver_label, VG_COLOR_GRAY, 0);
  lv_obj_set_style_text_font(ver_label, &lv_font_montserrat_10, 0);

  return row;
}

static lv_obj_t *vg_create_status_card(lv_obj_t *parent, const char *title,
                                       lv_color_t accent_color)
{
  lv_obj_t *card = lv_obj_create(parent);
  lv_obj_t *title_label;
  lv_obj_t *dot;
  lv_obj_t *value;

  lv_obj_set_size(card, VG_CARD_W, VG_STATUS_AREA_H);
  lv_obj_set_style_bg_color(card, VG_COLOR_CARD_BG, 0);
  lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(card, 1, 0);
  lv_obj_set_style_border_color(card, accent_color, 0);
  lv_obj_set_style_radius(card, 4, 0);
  lv_obj_set_style_pad_all(card, 4, 0);
  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_SPACE_BETWEEN,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  title_label = lv_label_create(card);
  lv_label_set_text(title_label, title);
  lv_obj_set_style_text_color(title_label, accent_color, 0);
  lv_obj_set_style_text_font(title_label, &lv_font_montserrat_10, 0);

  dot = lv_obj_create(card);
  lv_obj_set_size(dot, 12, 12);
  lv_obj_set_style_bg_color(dot, VG_COLOR_GRAY, 0);
  lv_obj_set_style_bg_opa(dot, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(dot, 6, 0);
  lv_obj_set_style_border_width(dot, 0, 0);

  value = lv_label_create(card);
  lv_label_set_text(value, "---");
  lv_obj_set_style_text_color(value, VG_COLOR_TEXT, 0);
  lv_obj_set_style_text_font(value, &lv_font_montserrat_12, 0);

  return card;
}

static void vg_create_status_area(lv_obj_t *parent)
{
  lv_obj_t *area = lv_obj_create(parent);

  lv_obj_set_size(area, VG_SCREEN_W - 8, VG_STATUS_AREA_H);
  lv_obj_align(area, LV_ALIGN_TOP_LEFT, 4, VG_STATUS_AREA_Y);
  lv_obj_set_style_bg_color(area, VG_COLOR_BG, 0);
  lv_obj_set_style_bg_opa(area, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(area, 0, 0);
  lv_obj_set_style_radius(area, 0, 0);
  lv_obj_set_style_pad_all(area, 0, 0);
  lv_obj_set_flex_flow(area, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(area, LV_FLEX_ALIGN_SPACE_EVENLY,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  vg_create_status_card(area, "Acquire", VG_COLOR_GREEN);
  vg_create_status_card(area, "Alarm", VG_COLOR_RED);
  vg_create_status_card(area, "Network", VG_COLOR_BLUE);
  vg_create_status_card(area, "Audio", VG_COLOR_YELLOW);
  vg_create_status_card(area, "Time", VG_COLOR_GRAY);
}

void vg_ui_home_create(void)
{
  lv_obj_t *scr = lv_screen_active();

  lv_obj_set_style_bg_color(scr, VG_COLOR_BG, 0);
  lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);

  vg_create_title_bar(scr);
  vg_create_info_row(scr);
  vg_create_status_area(scr);
}

