# Map the WSL contest repo to a Windows drive letter so C/C++ IntelliSense works.
# Microsoft cpptools cannot produce IL ("No IL available") when the workspace is a
# UNC path like \\wsl.localhost\Debian\...
#
# Usage (Windows PowerShell):
#   .\scripts\windows_map_wsl_workspace.ps1
#   code V:\
#
# Then open files from V:\ not from \\wsl.localhost\...

[CmdletBinding()]
param(
  [string]$DriveLetter = "V",
  [string]$WslDistro = "Debian",
  [string]$WslRepoPath = "/home/debian19y/openvela/contest2026_004_TeamFalcons",
  [switch]$OpenInCode
)

$ErrorActionPreference = "Stop"

$letter = $DriveLetter.TrimEnd(':')
if ($letter.Length -ne 1) {
  throw "DriveLetter must be a single letter, e.g. V"
}

# Prefer \\wsl$\ which is often more reliable for net use than \\wsl.localhost\
$uncCandidates = @(
  "\\wsl$\$WslDistro$($WslRepoPath -replace '/','\')",
  "\\wsl.localhost\$WslDistro$($WslRepoPath -replace '/','\')"
)

$unc = $null
foreach ($candidate in $uncCandidates) {
  if (Test-Path -LiteralPath $candidate) {
    $unc = $candidate
    break
  }
}

if ($null -eq $unc) {
  throw "Could not find WSL repo via UNC. Tried: $($uncCandidates -join ', ')"
}

$root = "${letter}:"
$existing = Get-PSDrive -Name $letter -ErrorAction SilentlyContinue
if ($existing) {
  Write-Host "Drive $root already exists -> $($existing.DisplayRoot)"
} else {
  Write-Host "Mapping $root => $unc"
  net use $root $unc /persistent:yes | Out-Host
  if ($LASTEXITCODE -ne 0) {
    throw "net use failed with exit code $LASTEXITCODE"
  }
}

if (-not (Test-Path -LiteralPath (Join-Path $root "app\velaguard_app"))) {
  throw "Mapped drive $root does not look like the contest repo (missing app\velaguard_app)."
}

Write-Host ""
Write-Host "OK. Open THIS path in Windows VS Code (not UNC):"
Write-Host "  $root\"
Write-Host ""
Write-Host "Then:"
Write-Host "  1) C/C++: Reset IntelliSense Database"
Write-Host "  2) Developer: Reload Window"
Write-Host "  3) Open app\velaguard_app\velaguard_main.c and try F12 / Ctrl+Space"
Write-Host ""
Write-Host "Build/flash tasks still work (they call WSL + Windows Cube tools)."

if ($OpenInCode) {
  if (Get-Command code -ErrorAction SilentlyContinue) {
    code $root
  } else {
    Write-Host "note: 'code' CLI not found; open $root manually in VS Code."
  }
}

