# Mirror the contest repo onto a REAL Windows NTFS folder so VS Code does not
# auto-switch into WSL Remote (which breaks C/C++ IntelliSense).
#
# Symlinks to \\wsl$\... still count as WSL paths for VS Code Remote.
# This script copies the working tree to:
#   %USERPROFILE%\velaguard-win
#
# Edit/IntelliSense: open that Windows folder.
# Build/flash: still runs against the WSL tree via existing scripts.
#
# Usage (Windows PowerShell):
#   powershell -ExecutionPolicy Bypass -File scripts\windows_sync_workspace_to_ntfs.ps1
#   code %USERPROFILE%\velaguard-win

[CmdletBinding()]
param(
  [string]$WslDistro = "Debian",
  [string]$WslRepoPath = "/home/debian19y/openvela/contest2026_004_TeamFalcons",
  [string]$DestPath = "$env:USERPROFILE\velaguard-win",
  [switch]$OpenInCode,
  [switch]$Full
)

$ErrorActionPreference = "Stop"

$srcCandidates = @(
  ("\\wsl$\{0}{1}" -f $WslDistro, ($WslRepoPath -replace '/', '\')),
  ("\\wsl.localhost\{0}{1}" -f $WslDistro, ($WslRepoPath -replace '/', '\'))
)

$src = $null
foreach ($c in $srcCandidates) {
  if (Test-Path -LiteralPath (Join-Path $c "app\velaguard_app")) {
    $src = $c
    break
  }
}
if ($null -eq $src) {
  throw "Cannot reach WSL contest repo. Is distro '$WslDistro' running?"
}

Write-Host "Source: $src"
Write-Host "Dest  : $DestPath"

New-Item -ItemType Directory -Force -Path $DestPath | Out-Null

# Always mirror what IntelliSense and day-to-day editing need.
$paths = @(
  "app",
  ".vscode",
  "scripts",
  "docs",
  "board",
  "README.md",
  "CONTEXT.md",
  "AGENTS.md",
  "CLAUDE.md",
  "harness"
)

if ($Full) {
  $paths += @("logs", ".scratch", ".trellis", "VelaGuard_项目手册.md", "VelaGuard_推进方案.md")
}

foreach ($rel in $paths) {
  $from = Join-Path $src $rel
  $to = Join-Path $DestPath $rel
  if (-not (Test-Path -LiteralPath $from)) {
    Write-Host "skip missing: $rel"
    continue
  }

  $item = Get-Item -LiteralPath $from -Force
  if ($item.PSIsContainer) {
    New-Item -ItemType Directory -Force -Path $to | Out-Null
    Write-Host "robocopy $rel ..."
    # /MIR keeps Windows tree aligned with WSL for these folders.
    & robocopy $from $to /MIR /R:1 /W:1 /NFL /NDL /NJH /NJS /XD .debug third_party\nanomodbus\tests third_party\nanomodbus\examples | Out-Null
    $rc = $LASTEXITCODE
    if ($rc -ge 8) {
      throw "robocopy failed for $rel (exit $rc)"
    }
  } else {
    $parent = Split-Path -Parent $to
    New-Item -ItemType Directory -Force -Path $parent | Out-Null
    Copy-Item -LiteralPath $from -Destination $to -Force
    Write-Host "copy $rel"
  }
}

# Marker so users know this is a mirror
@"
This folder is a Windows NTFS mirror of the WSL contest repo for VS Code IntelliSense.

- Source (authoritative for git/build): $WslRepoPath in WSL
- Refresh mirror: scripts\windows_sync_workspace_to_ntfs.ps1
- Build/flash: use scripts\windows_build_openvela.ps1 / windows_flash_cube.ps1
  (they still compile the WSL tree)

Do not open \\wsl.localhost\... if you need autocomplete.
"@ | Set-Content -Path (Join-Path $DestPath "WINDOWS_MIRROR_README.txt") -Encoding UTF8

# Force workspace settings that discourage Remote-WSL takeover on this copy
$settingsPath = Join-Path $DestPath ".vscode\settings.json"
if (Test-Path -LiteralPath $settingsPath) {
  try {
    $json = Get-Content -LiteralPath $settingsPath -Raw | ConvertFrom-Json
  } catch {
    $json = [pscustomobject]@{}
  }
} else {
  New-Item -ItemType Directory -Force -Path (Split-Path $settingsPath) | Out-Null
  $json = [pscustomobject]@{}
}

# These help keep the window local when possible
Add-Member -InputObject $json -NotePropertyName "remote.autoForwardPorts" -NotePropertyValue $false -Force
Add-Member -InputObject $json -NotePropertyName "remote.WSL.serverInstallPath" -NotePropertyValue @{} -Force

($json | ConvertTo-Json -Depth 20) | Set-Content -Path $settingsPath -Encoding UTF8

Write-Host ""
Write-Host "OK. Open THIS folder (real NTFS path, not UNC, not WSL Remote):"
Write-Host "  $DestPath"
Write-Host ""
Write-Host "In VS Code:"
Write-Host "  File -> Open Folder -> $DestPath"
Write-Host "  If prompted 'Reopen in WSL', choose Stay Local / Don't Remote"
Write-Host "  Then: C/C++ Reset IntelliSense Database + Reload Window"

if ($OpenInCode) {
  $codeCands = @(
    "$env:LOCALAPPDATA\Programs\Microsoft VS Code\Code.exe",
    "$env:ProgramFiles\Microsoft VS Code\Code.exe"
  )
  $code = $codeCands | Where-Object { Test-Path $_ } | Select-Object -First 1
  if ($code) {
    # --new-window and file path without remote authority
    Start-Process -FilePath $code -ArgumentList @("--new-window", $DestPath)
    Write-Host "Launched: $code $DestPath"
  } else {
    Write-Host "VS Code executable not found; open the folder manually."
  }
}

