input.newString:
# Critical paths: failure aborts (needed for firmware correctness).
# Optional paths: warn and continue (e.g. root-owned AGENTS.md on WSL).
$criticalPaths = @(
  "app",
  "scripts",
  "board"
)
$optionalPaths = @(
  ".vscode",
  "docs",
  "README.md",
  "CONTEXT.md",
  "AGENTS.md",
  "CLAUDE.md",
  "harness"
)

if ($Full) {
  $optionalPaths += @("logs", ".scratch", ".trellis", "VelaGuard_项目手册.md", "VelaGuard_推进方案.md")
}

function Sync-OnePath {
  param(
    [Parameter(Mandatory = $true)][string]$Rel,
    [Parameter(Mandatory = $true)][bool]$Critical
  )

  $from = Join-Path $fromRoot $Rel
  $to = Join-Path $toRoot $Rel
  if (-not (Test-Path -LiteralPath $from)) {
    Write-Host "skip missing: $Rel"
    return
  }

  try {
    $item = Get-Item -LiteralPath $from -Force
    if ($item.PSIsContainer) {
      New-Item -ItemType Directory -Force -Path $to | Out-Null
      Write-Host "robocopy $Rel ..."
      if ($Reverse) {
        & robocopy $from $to /E /XO /R:1 /W:1 /NFL /NDL /NJH /NJS /XD .debug third_party\nanomodbus\tests third_party\nanomodbus\examples | Out-Null
      } else {
        & robocopy $from $to /MIR /R:1 /W:1 /NFL /NDL /NJH /NJS /XD .debug third_party\nanomodbus\tests third_party\nanomodbus\examples | Out-Null
      }
      $rc = $LASTEXITCODE
      if ($rc -ge 8) {
        throw "robocopy failed for $Rel (exit $rc)"
      }
    } else {
      $parent = Split-Path -Parent $to
      if (-not [string]::IsNullOrWhiteSpace($parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
      }
      Copy-Item -LiteralPath $from -Destination $to -Force -ErrorAction Stop
      Write-Host "copy $Rel"
    }
  } catch {
    if ($Critical) {
      throw
    }
    Write-Host "warning: skip non-critical '$Rel': $($_.Exception.Message)"
  }
}

foreach ($rel in $criticalPaths) {
  Sync-OnePath -Rel $rel -Critical $true
}
foreach ($rel in $optionalPaths) {
  Sync-OnePath -Rel $rel -Critical $false
}
